import React from 'react';
import {AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {Paper} from './Paper';
import {Hand} from './components/Hand';
import {ParallaxPlate, Layer} from './components/ParallaxPlate';
import {CAVEAT, textWidth} from './lib/fonts';
import {DAYBREAK} from './theme';
import {samplePath, drawnPath, pointAt, totalLength, arrowHead, Pt} from './lib/stroke';

// The sample plate: sea-of-ice, three depth layers (generated by depth_layers on CI).
const LAYERS: Layer[] = [
  {file: 'art/CL-11/layers/plate-sea-of-ice.L0.png', parallax: 0.01},
  {file: 'art/CL-11/layers/plate-sea-of-ice.L1.png', parallax: 0.045},
  {file: 'art/CL-11/layers/plate-sea-of-ice.L2.png', parallax: 0.09},
];

const LABEL = 'the real monster?';
const LABEL_SIZE = 76;
const LABEL_X = 430;
const LABEL_Y = 300; // baseline
const ARROW_PTS: Pt[] = [
  {x: 560, y: 330},
  {x: 740, y: 470},
  {x: 940, y: 610},
]; // from under the label, curving to a feature in the ice

export const HandSample: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();

  // Camera runs across the whole scene.
  const camT = frame / durationInFrames;

  // ---- phase timing (frames @30fps) ----
  const writeStart = 45;
  const writeEnd = 255; // ~7s to write the label (~2.4 cps)
  const arrowStart = 300;
  const arrowEnd = 430;
  const handGone = 470;

  // ---- label writing ----
  const writeP = interpolate(frame, [writeStart, writeEnd], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const nChars = Math.round(writeP * LABEL.length);
  const visible = LABEL.slice(0, nChars);
  const labelNibX = LABEL_X + textWidth(visible, LABEL_SIZE);

  // ---- arrow drawing ----
  const samples = samplePath(ARROW_PTS);
  const arrowP = interpolate(frame, [arrowStart, arrowEnd], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const arrowD = drawnPath(samples, arrowP);
  const arrowNib = pointAt(samples, arrowP);
  const headFrac = interpolate(arrowP, [0.82, 1], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const heads = arrowHead(pointAt(samples, 1), pointAt(samples, 0.9), 30);

  // ---- hand placement: follows whichever stroke is active, else lifts away ----
  let hx = labelNibX;
  let hy = LABEL_Y;
  let down = 0;
  let variant: 'write' | 'point' = 'write';
  if (frame >= writeStart && frame < writeEnd + 12) {
    hx = labelNibX;
    hy = LABEL_Y - 6;
    down = interpolate(frame, [writeStart, writeStart + 10, writeEnd, writeEnd + 12], [0, 1, 1, 0], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
  } else if (frame >= arrowStart - 14 && frame < handGone) {
    hx = arrowNib.x;
    hy = arrowNib.y;
    down = interpolate(frame, [arrowStart - 14, arrowStart, arrowEnd, handGone], [0, 1, 1, 0], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
  }
  const handOpacity = frame >= handGone ? interpolate(frame, [handGone, handGone + 20], [1, 0], {extrapolateRight: 'clamp'}) : 1;

  const inkIn = interpolate(frame, [0, 30], [0, 1], {extrapolateRight: 'clamp'});

  return (
    <Paper>
      <AbsoluteFill style={{opacity: inkIn}}>
        <ParallaxPlate layers={LAYERS} camera="drift" progress={camT} />
      </AbsoluteFill>

      {/* ink annotations drawn on the plate */}
      <AbsoluteFill>
        <svg width="100%" height="100%" style={{position: 'absolute', inset: 0}}>
          {/* underline grows under the label as it's written */}
          <line
            x1={LABEL_X}
            y1={LABEL_Y + 16}
            x2={LABEL_X + textWidth(visible, LABEL_SIZE)}
            y2={LABEL_Y + 16}
            stroke={DAYBREAK.coral}
            strokeWidth={5}
            strokeLinecap="round"
          />
          {/* arrow shaft */}
          <path d={arrowD} fill="none" stroke={DAYBREAK.coral} strokeWidth={6} strokeLinecap="round" strokeLinejoin="round" />
          {/* arrowhead */}
          {headFrac > 0 &&
            heads.map((seg, i) => (
              <line
                key={i}
                x1={seg[0].x}
                y1={seg[0].y}
                x2={seg[0].x + (seg[1].x - seg[0].x) * headFrac}
                y2={seg[0].y + (seg[1].y - seg[0].y) * headFrac}
                stroke={DAYBREAK.coral}
                strokeWidth={6}
                strokeLinecap="round"
              />
            ))}
        </svg>
        <div
          style={{
            position: 'absolute',
            left: LABEL_X,
            top: LABEL_Y,
            transform: 'translateY(-0.78em)',
            fontFamily: CAVEAT,
            fontSize: LABEL_SIZE,
            color: DAYBREAK.ink,
            whiteSpace: 'pre',
            lineHeight: 1,
          }}
        >
          {visible}
        </div>
      </AbsoluteFill>

      {down > 0.02 && handOpacity > 0 && (
        <div style={{opacity: handOpacity}}>
          <Hand x={hx} y={hy} variant={variant} down={down} scale={0.92} />
        </div>
      )}
    </Paper>
  );
};
